SELECT r.*, u.username, u.nickname, u.avatar, COALESCE(like_count.like_count, 0) as like_count FROM review r LEFT JOIN user u ON r.user_id = u.id LEFT JOIN ( SELECT review_id, COUNT(*) as like_count FROM review_like GROUP BY review_id ) like_count ON r.id = like_count.review_id WHERE r.movie_id = #{movieId}
ORDER BY like_count DESC, r.create_time DESC
ORDER BY r.create_time DESC
LIMIT #{offset}, #{size}

SELECT r.*, m.title as movie_title, m.poster as movie_poster
FROM review r
LEFT JOIN movie m ON r.movie_id = m.id
WHERE r.user_id = #{userId}
ORDER BY r.create_time DESC
LIMIT #{offset}, #{size}
